#!/bin/bash
# Quick setup script for PostgreSQL environment

set -e

echo "PostgreSQL Environment Setup"
echo "=============================="
echo ""

# Check if .env already exists
if [ -f .env ]; then
    echo "⚠ .env file already exists"
    read -p "Overwrite? (y/N): " -n 1 -r
    echo
    if [[ ! $REPLY =~ ^[Yy]$ ]]; then
        echo "Cancelled. Edit .env manually if needed."
        exit 0
    fi
fi

# Generate a random password
PASSWORD=$(openssl rand -base64 32 | tr -d "=+/" | cut -c1-25)

# Create .env file
cat > .env << EOF
# PostgreSQL Database Configuration
# Generated by setup_env.sh

POSTGRES_DB=benchmark
POSTGRES_USER=benchmark_user
POSTGRES_PASSWORD=${PASSWORD}
POSTGRES_HOST=localhost
POSTGRES_PORT=5433
DATABASE_TYPE=postgresql

# SQLite path (only used if DATABASE_TYPE=sqlite)
SQLITE_PATH=benchmark/benchmark.db
EOF

echo "✓ Created .env file with generated password"
echo ""
echo "Configuration:"
echo "  Database: benchmark"
echo "  User: benchmark_user"
echo "  Password: ${PASSWORD}"
echo "  Host: localhost"
echo "  Port: 5433"
echo ""
echo "Next steps:"
echo "  1. Start PostgreSQL: docker-compose up -d"
echo "  2. Verify config: python benchmark/check_config.py"
echo "  3. Run migration: python benchmark/migrate_to_postgres.py"
echo ""
